// Sample batch of AI assistant responses to evaluate.
// Swap this for a Google Sheets / CSV / database read in production.
const batch = [
  { id: 'R1', userGoal: 'Decide whether to approve a change request before a maintenance window',
    response: 'Change CR-4821 looks fine. Approve it.' },
  { id: 'R2', userGoal: 'Understand why an operational alert fired and what to do',
    response: 'Alert A-77 fired on node EU-3 at 02:14 due to memory pressure (92% for 10 min). Likely cause: batch job BJ-12 overlap. Suggested next step: reschedule BJ-12 outside the 02:00-03:00 window. This is reversible and needs no restart.' },
  { id: 'R3', userGoal: 'Get a maintenance plan summary for a technician heading on-site',
    response: 'There are several maintenance items. Please review the plan in the system for details on each task, including open ones, completed ones, and any that might be overdue or upcoming depending on scheduling.' }
];
return batch.map(r => ({ json: r }));

// Runs once PER response. Build the OpenAI chat-completions request that scores it.
const r = $json;

// CHANGE THIS to a model your LiteLLM gateway serves.
// Not sure what it serves? Open http://localhost:5678/litellm/v1/models in a browser,
// or check the model dropdown of a native n8n OpenAI node.
const MODEL = 'gpt-4o';

const rubric = `Score this AI assistant response on six dimensions, each 0-3 (0 = fails, 3 = excellent):
1. Value Alignment: addresses the user's actual goal, not just the literal query.
2. Output Completeness: contains what's needed to act, without noise.
3. Format Accuracy: presented in a form fit for the use (scan vs read, steps vs prose).
4. Cognitive Load: low interpretation effort; decisions and next steps disambiguated.
5. Trust Calibration: signals uncertainty, verification needs, and reversibility appropriately.
6. Interaction Efficiency: minimal steps to act; any automation proposed with appropriate control.`;

const prompt = `${rubric}

USER GOAL: ${r.userGoal}
AI RESPONSE: ${r.response}

Return ONLY valid minified JSON, no markdown fences:
{"scores":[{"dimension":"Value Alignment","score":0,"note":""},{"dimension":"Output Completeness","score":0,"note":""},{"dimension":"Format Accuracy","score":0,"note":""},{"dimension":"Cognitive Load","score":0,"note":""},{"dimension":"Trust Calibration","score":0,"note":""},{"dimension":"Interaction Efficiency","score":0,"note":""}],"verdict":"one sentence"}`;

return { json: { id: r.id, userGoal: r.userGoal, response: r.response, requestBody: {
  model: MODEL,
  messages: [
    { role: 'system', content: 'You are a senior UX evaluator. Return only valid JSON.' },
    { role: 'user', content: prompt }
  ],
  response_format: { type: 'json_object' },
  temperature: 0
} } };

// Pair each model result with its source response, score, prioritise, render Markdown.
const scored = $input.all();
const metas = $('Build eval request').all();
const THRESHOLD = 12; // out of 18

function extractJson(s) {
  if (!s) return null;
  let t = String(s).trim();
  const fence = t.match(/```(?:json)?\s*([\s\S]*?)```/i);
  if (fence) t = fence[1].trim();
  if (t[0] !== '{') { const a = t.indexOf('{'), b = t.lastIndexOf('}'); if (a >= 0 && b > a) t = t.slice(a, b + 1); }
  try { return JSON.parse(t); } catch (e) { return null; }
}

const rows = scored.map((item, i) => {
  const meta = metas[i] ? metas[i].json : {};
  const j = item.json || {};
  // OpenAI-compatible shape first, then fall back to native-node / raw shapes.
  const text = j.choices?.[0]?.message?.content ?? j.message?.content ?? j.content ?? j.text ?? '';
  const parsed = extractJson(text);
  const scores = parsed?.scores || [];
  const total = scores.reduce((s, d) => s + (Number(d.score) || 0), 0);
  return {
    id: meta.id, userGoal: meta.userGoal, response: meta.response,
    total, max: scores.length * 3, scores,
    verdict: parsed?.verdict || (parsed ? '' : 'PARSE FAILED - check the model output'),
    flagged: !parsed || total < THRESHOLD
  };
});

const avg = rows.length ? (rows.reduce((s, r) => s + r.total, 0) / rows.length).toFixed(1) : '0';
const flagged = rows.filter(r => r.flagged);

let md = `# Agent-Output Evaluation\n\n`;
md += `**Responses scored:** ${rows.length}\n`;
md += `**Average score:** ${avg}/18\n`;
md += `**Flagged for human review (< ${THRESHOLD}/18):** ${flagged.length}\n\n`;
md += `## Per-response scores (lowest first)\n`;
rows.sort((a, b) => a.total - b.total).forEach(r => {
  md += `\n### ${r.id} - ${r.total}/${r.max}${r.flagged ? '  [flag] review' : ''}\n`;
  md += `**Goal:** ${r.userGoal}\n\n`;
  md += `**Verdict:** ${r.verdict}\n\n`;
  r.scores.forEach(d => { md += `- ${d.dimension}: ${d.score}/3 - ${d.note}\n`; });
});

return [{ json: { averageScore: avg, flaggedCount: flagged.length, rows, report: md } }];
